def backfill_proof_hashes(apps, schema_editor):
    """Hash the receipts already on disk so duplicates of old payments are caught too."""
    import hashlib

    ManualPayment = apps.get_model("z_auth", "ManualPayment")
    for payment in ManualPayment.objects.exclude(proof="").filter(proof_sha256=""):
        digest = hashlib.sha256()
        try:
            with payment.proof.open("rb") as f:
                for chunk in f.chunks():
                    digest.update(chunk)
        except (OSError, ValueError):
            continue
        ManualPayment.objects.filter(pk=payment.pk).update(proof_sha256=digest.hexdigest())


